import * as Types from '@paulirish/trace_engine/models/trace/types/types.js';

import {Phase} from './phase.js';
import {mimeLookup} from '../../../third_party/mimetypes.js';
import {toMicrosec, baseEvt, frameData} from './trace.js';

/** @import {Types} from '@paulirish/trace_engine' */
/** @import {Network} from '@paulirish/trace_engine/generated/protocol.js' */
/** @typedef {Types.Timing.Milli} MilliSeconds */
/** @typedef {{frame: string, name: string, processId: number, url: string, navigationId: string}} FrameData */

/**
 * @param {PerformanceResourceTiming | PerformanceNavigationTiming} entry
 * @param {string} requestId
 * @return {Types.Events.Event[]}
 */
export function innerConstructNetworkRequest(entry, requestId) {
  const baseNetworkEvt = {
    ...baseEvt,
    ts: toMicrosec(entry.startTime),
    ph: Phase.INSTANT,
    s: /** @type {Types.Events.Scope.THREAD} */ ('t'),
  };
  /** @param {number} timing */
  const relativeToReq = timing => /** @type MilliSeconds */ (timing - entry.startTime);

  const renderBlocking = entry.renderBlockingStatus === 'non-blocking' ? 'non_blocking' : entry.renderBlockingStatus === 'blocking' ? 'blocking' : undefined;

  /** @param {PerformanceResourceTiming | PerformanceNavigationTiming} entry */
  const resolveMimeType = entry => {
    // Hack to help resolve more. eg https://stackbounce.h5games.usercontent.goog/v/1aqsvv0aegbjg/images/hd_res_tall.jpeg=s800-rw-nd-v1
    const url = entry.name.replaceAll('=', '?=');
    // Hack to resolve more. eg https://fonts.googleapis.com/css?family=Roboto+Mono:400
    const filename = URL.parse(url)?.pathname.replace(/^\//, '');
    const extension = filename?.split('.').pop();
    // Fall back to octet-stream (as devtools frontend does, if we can't guess at mimetype)
    const mimeType =
      entry.entryType === 'navigation'
        ? 'text/html'
        : (extension && /** @type {{[key: string]: string}} */ (mimeLookup)[extension]) || 'application/octet-stream';
    return mimeType;
  };

  /**
   * Maps Resource Timing initiatorType (https://w3c.github.io/resource-timing/#dom-performanceresourcetiming-initiatortype) to traceEvent initaitorType
   * @type {Readonly<Record<string, string>>}
   */
  const requestInitiatorToEnumMap = {
    // Navigation requests are often parser-initiated or a specific user action
    // but conceptually they are distinct, I'll map it to Parser for now.
    navigation: 'parser',
    css: 'parser', // CSS processing is part of parsing/rendering
    script: 'script',
    xmlhttprequest: 'script',
    fetch: 'script',
    beacon: 'script', // sendBeacon is a script API
    video: 'parser', // <video> element's src
    audio: 'parser', // <audio> element's src
    track: 'parser', // <track> element's src
    img: 'parser', // <img> element's src/srcset
    image: 'parser', // <image> element (SVG)
    input: 'parser', // <input type="image">
    a: 'parser', // <a> download/ping
    iframe: 'parser', // <iframe> src
    frame: 'parser', // <frame> loading
    other: 'other',
  };

  // ALSO... TODO: ResourceWillSendRequest events exist for the navigation document. but... devtools doesnt make a whisker for it.. but probably should.

  /** @type {Types.Events.ResourceSendRequest} */
  const sendReq = {
    ...baseNetworkEvt,
    ts: toMicrosec(entry.startTime),
    name: 'ResourceSendRequest',
    args: {
      data: {
        requestId,
        frame: frameData.frame,
        url: entry.name,
        priority: renderBlocking === 'blocking' ? /** @type {Network.ResourcePriority.High} */ ('High') : /** @type {Network.ResourcePriority.Low} */ ('Low'),
        renderBlocking: renderBlocking,
        // Added those as default values since they are missing.
        // TODO: we should establish them from the actual resource entry
        resourceType: /** @type {Network.ResourceType.Other} */ ('Other'),
        fetchPriorityHint: 'auto',
        initiator: entry.initiatorType
          ? {
              // This is probably imperfect but so close.
              type: /** @type {Types.Events.Initiator['type']} */ (requestInitiatorToEnumMap[entry.initiatorType] || 'other'),
              fetchType: entry.initiatorType,
            }
          : undefined,
      },
    },
  };

  // because crossorigin sets responsestart to 0
  const responseStartMs = Math.max(entry.startTime, entry.responseStart);

  /** @type {Types.Events.ResourceReceiveResponse} */
  const receiveResp = {
    ...baseNetworkEvt,
    name: 'ResourceReceiveResponse',
    ts: toMicrosec(responseStartMs),
    args: {
      data: {
        requestId,
        protocol: entry.nextHopProtocol || 'unknown', // TODO: select something from http/0.9, http/1.0, http/1.1, http, h2, h3,   h3-Q050, data, blob
        connectionId: 0,
        connectionReused: false,
        encodedDataLength: 0, // entry.transferSize, // TODO: Gotta resolve the transfer size numbers needed for RPP.
        fromCache: entry.deliveryType === 'cache',
        fromServiceWorker: entry.workerStart !== 0,
        frame: frameData.frame,
        mimeType: resolveMimeType(entry),
        // Trace value for responseTime looks like unix epoch in seconds. dunno what the point of that is.
        // This is ignored in RPP
        responseTime: Types.Timing.Milli(responseStartMs),
        statusCode: entry.responseStatus || 200, // not sure if 200 is a sane default
        timing: {
          // While the rest of timing is relative to the request, this is a actual timestamp.
          requestTime: Types.Timing.Seconds(entry.startTime / 1000), // requestTime is in SECONDS (lol)

          // All these timings should be relative to the requestTime. Also they're in millisec.
          connectEnd: /** @type MilliSeconds */ (-1),
          connectStart: /** @type MilliSeconds */ (-1),
          dnsEnd: /** @type MilliSeconds */ (-1),
          dnsStart: /** @type MilliSeconds */ (-1),
          proxyEnd: /** @type MilliSeconds */ (-1),
          proxyStart: /** @type MilliSeconds */ (-1),
          pushEnd: /** @type MilliSeconds */ (0),
          pushStart: /** @type MilliSeconds */ (0),
          sendStart: relativeToReq(entry.requestStart),
          sendEnd: relativeToReq(entry.requestStart),
          receiveHeadersEnd: relativeToReq(entry.responseStart),
          sslEnd: /** @type MilliSeconds */ (-1),
          sslStart: /** @type MilliSeconds */ (-1),
          workerReady: /** @type MilliSeconds */ (-1),
          workerStart: /** @type MilliSeconds */ (-1),
          receiveHeadersStart: relativeToReq(entry.responseStart),
        },
      },
    },
  };

  const responseEndMs =
    entry.entryType === 'navigation'
      ? // Nav Timing ends at loadEventEnd: https://w3c.github.io/navigation-timing/#performanceentry
        // But responseEnd is end of the network request.
        entry.responseEnd
      : // For resource-timing, I have no reason to think these two values aren't identical.
        Math.max(entry.responseEnd, entry.startTime + entry.duration);

  /** @type {Types.Events.ResourceFinish} */
  const resFinish = {
    ...baseNetworkEvt,
    name: 'ResourceFinish',
    // This .ts controls the right whisker. We _could_ use onload handlers to find where they land. But.. eh.
    ts: toMicrosec(responseEndMs), // monotonic. microsec.
    args: {
      data: {
        requestId,
        finishTime: Types.Timing.Seconds(responseEndMs / 1000), // Monotonic timescale, but in seconds.
        encodedDataLength: entry.transferSize, // there's also entry.encodedBodySize but i think this should include headers?
        decodedBodyLength: entry.decodedBodySize,
        didFail: false,
      },
    },
  };

  return [sendReq, receiveResp, resFinish];
}
