import * as Types from '@paulirish/trace_engine/models/trace/types/types.js';

import {selfProfileToCPUProfile} from '../cpuprofile.js';
import {innerConstructNetworkRequest} from './network.js';
import {innerHandleLongTask, innerHandleLoAF} from './loaf.js';

import {Phase} from './phase.js';
import {enhanceWithSources} from './sources.js';

/** @import {DOM} from '@paulirish/trace_engine/generated/protocol.js' */
/** @import * as CPUProfileDataModel from '@paulirish/trace_engine/models/cpu_profile/CPUProfileDataModel.js' */
/** @import * as PerfEntries from '../../../types/perfentries' */
/** @import {FieldTrace}  from '../../../types/fieldtrace.js' */
/** @import * as ChromiumTrace from '../../../types/chromium-trace.js' */

/** @param {number} milliNum */
export const toMicrosec = milliNum => /** @type {Types.Timing.Micro} */ (milliNum * 1000);
export const Ms = Types.Timing.Milli;
export const μs = Types.Timing.Micro; // Btw you can type a µ on Mac with Option-m

/** @type {Types.Events.Event[]} */
export let currentTrace = [];

let i = 0;
const getId = () => /** @type {Types.Events.ProfileID} */ (`0x${(i++).toString(16)}`);
let totalInteractionCount = 0;

/** @type {Types.Events.Event} */
export const baseEvt = {
  cat: 'devtools.timeline',
  pid: Types.Events.ProcessID(7),
  tid: Types.Events.ThreadID(9),

  ph: Phase.COMPLETE,
  args: {},
  // Hack: Use one to avoid some mishandling in the devtools of valid trace events
  // with a ts of 0. We should fix the bug there, but making this a microsecond off
  // seems an okay tradeoff.
  ts: μs(1),
  name: 'UNSET_NAME',
};

export const frameData = {
  processId: baseEvt.pid,
  frame: '_frameid_',
  name: '_frame_name_',
  url: 'https://www.UNSET_URL.com/',
  navigationId: '_navid_',
};

export function reset() {
  currentTrace.length = 0;
  i = 0;
  addBaselineTraceEvents();
}

/** @param {PerformanceMark|PerformanceMeasure} entry */
export function craftUTEvent(entry) {
  /** @type {Types.Events.Event} */
  const markEvt = {
    ...baseEvt,
    name: entry.name,
    cat: 'blink.user_timing',
    ts: toMicrosec(entry.startTime),
    ph: Phase.INSTANT,
  };

  // {"args":{"data":{"navigationId":"570B8D5DF2E8C9BABF5C2C206241F77A","startTime":131}},"cat":"blink.user_timing","name":"endOfDOM","ph":"I","pid":40367,"s":"t","tid":259,"ts":114602162835,"tts":392842,"selfTime":0},
  if (entry.entryType === 'mark') {
    return currentTrace.push(markEvt);
  }

  // OK. We have a measure.

  // {"args":{"startTime":127.70000000298023},"cat":"blink.user_timing","id2":{"local":"0x103"},"name":"evaling scripts","ph":"b","pid":40367,"tid":259,"ts":114602159514},
  // {"args":{},"cat":"blink.user_timing","id2":{"local":"0x103"},"name":"evaling scripts","ph":"e","pid":40367,"tid":259,"ts":114602162835},
  const measureBegin = {
    ...markEvt,
    id2: {local: getId()},
    ph: Phase.ASYNC_NESTABLE_START,
  };
  const measureEnd = {
    ...measureBegin,
    ph: Phase.ASYNC_NESTABLE_END,
    ts: toMicrosec(entry.startTime + entry.duration),
  };
  currentTrace.push(measureBegin, measureEnd);
}

/**
 * Used to visualize the entry within the Timings track
 *
 * @param {PerformanceEntry|PerfEntries.PerformanceScriptTiming} entry
 * @param {string=} trackName
 * @param {string=} entryName
 */
export function craftUserTimingForDebugging(entry, trackName, entryName) {
  /**
   * @type {Readonly<Record<string, Types.Extensions.ExtensionColorFromPalette>>}
   */
  const typeToColorMap = {
    navigation: 'primary',
    resource: 'primary',
    longtask: 'secondary',
    'long-animation-frame': 'tertiary',
    script: 'tertiary-light', // loaf script
    'layout-shift': 'secondary-dark',
    event: 'tertiary-light',
    paint: 'tertiary',
    'largest-contentful-paint': 'tertiary',
    'profiler-trace': 'secondary-dark',
    mark: 'tertiary-light',
    measure: 'tertiary-light',
    'first-input': 'primary-light',
    'visibility-state': 'secondary-light',
  };

  // @ts-expect-error Types don't allow non-strings here (YET).
  const entryMasqueradingAsString = /** @type {string} */ (entry);

  const detail = {
    // Create custom tracks with extra control over presentation: https://developer.chrome.com/docs/devtools/performance/extension
    devtools: /** @type {Types.Extensions.DevToolsObjEntry} */ ({
      dataType: 'track-entry',
      track: trackName,
      trackGroup: '🌱 fieldtrace',
      color: typeToColorMap[entry.entryType] ?? 'tertiary',
      // Include the full entry in here so it's visible in the devtools UI.
      properties: [['entry', entryMasqueradingAsString]],
    }),
    // Include raw perf entry data for presenting in devtools UI
    ...entry,
  };

  if (entry.entryType === 'script') {
    /** @type {PerfEntries.PerformanceScriptTiming} */
    // @ts-expect-error Poor casting here, but we know this is a script entry.
    const loafScript = entry;
    detail.devtools.tooltipText = `${loafScript.sourceFunctionName} ${loafScript.sourceURL}`;
  }

  /** @type {Types.Events.PerformanceMark} */
  const traceEvent = {
    ...baseEvt,
    name: entryName || `${entry.entryType}::${entry.name}`,
    cat: 'blink.user_timing',
    ts: toMicrosec(entry.startTime),
    args: {
      data: {
        // Smushing the whole thing into detail. Thanks alexnj!
        detail: JSON.stringify(detail),
      },
    },
    ph: Phase.INSTANT,
  };

  if (entry.entryType === 'mark' || entry.duration === 0) {
    currentTrace.push(traceEvent);
    return;
  }

  /** @type {Types.Events.PerformanceMeasureBegin} */
  const measureBegin = {
    ...traceEvent,
    id2: {local: getId()},
    ph: Phase.ASYNC_NESTABLE_START,
    args: {
      // It's on `args` on a measure, and `args.data` on a mark. Deal with it 8-D
      detail: JSON.stringify(detail),
    },
  };
  /** @type {Types.Events.PerformanceMeasureEnd} */
  const measureEnd = {
    ...measureBegin,
    ph: Phase.ASYNC_NESTABLE_END,
    ts: toMicrosec(entry.startTime + entry.duration),
  };

  // navTiming doesnt have starttime. its weird.
  if (entry.entryType === 'navigation') {
    const navEntry = /** @type {PerformanceNavigationTiming} */ (entry);
    // By definition the "navigationStart" == the time origin.
    // performance.timeOrigin holds a epoch timestamprequestId of it, but as a highres timestamp, it's guaranteed to be 0.
    // that said, we mostly want this data as resourcetiming excludes the document.
    // So we'll use fetchStart instead
    measureBegin.ts = toMicrosec(navEntry.fetchStart);
    measureBegin.dur = toMicrosec(measureBegin.ts + navEntry.responseEnd);
    measureEnd.ts = μs(measureBegin.ts + measureBegin.dur);
  }

  currentTrace.push(measureBegin, measureEnd);
}

/** @param {PerformanceResourceTiming | PerformanceNavigationTiming} entry */
export function constructNetworkRequest(entry) {
  currentTrace.push(...innerConstructNetworkRequest(entry, `${baseEvt.pid}.${++i}`));
}

/** @param {PerformanceNavigationTiming} entry */
export function handleNavigation(entry) {
  frameData.url = entry.name;

  // The request ID of the document should be the same as the navigation ID.
  currentTrace.push(...innerConstructNetworkRequest(entry, frameData.navigationId));

  // {"args":{"data":{"documentLoaderURL":"http://...","isLoadingMainFrame":true,"isOutermostMainFrame":true,"navigationId":"6DABE81A7285284668729CC73D2679EC"},"frame":"C45E6CB8A96AD582632AECC1CDCBDC57"}, "cat":"blink.user_timing","name":"navigationStart","ph":"R","pid":67459,"s":"t","tid":259,"ts":23479655245},
  currentTrace.push(
    /** @type {Types.Events.NavigationStart} */ ({
      ...baseEvt,
      name: 'navigationStart',
      cat: 'blink.user_timing',
      // Hack: Add one to avoid some mishandling in the devtools of valid trace events
      // with a ts of 0. We should fix the bug there, but making this a microsecond off
      // seems an okay tradeoff.
      ts: toMicrosec(entry.startTime) + 1, // hack to avoid valid, but zero .ts's.
      ph: Phase.MARK,
      args: {
        data: {
          documentLoaderURL: frameData.url,
          isLoadingMainFrame: true,
          isOutermostMainFrame: true,
          navigationId: frameData.navigationId,
        },
        frame: frameData.frame,
      },
    }),
  );

  currentTrace.push(
    /** @type {Types.Events.Dispatch} */ ({
      ...baseEvt,
      name: 'EventDispatch',
      ts: toMicrosec(entry.loadEventStart),
      dur: toMicrosec(entry.loadEventEnd - entry.loadEventStart),
      args: {
        data: {
          type: 'load',
        },
      },
    }),
  );

  currentTrace.push(
    /** @type {Types.Events.Dispatch} */ ({
      ...baseEvt,
      name: 'EventDispatch',
      ts: toMicrosec(entry.unloadEventStart),
      dur: toMicrosec(entry.unloadEventEnd - entry.unloadEventStart),
      args: {
        data: {
          type: 'unload',
        },
      },
    }),
  );

  currentTrace.push(
    /** @type {Types.Events.Dispatch} */ ({
      ...baseEvt,
      name: 'EventDispatch',
      ts: toMicrosec(entry.domContentLoadedEventStart),
      dur: toMicrosec(entry.domContentLoadedEventEnd - entry.domContentLoadedEventStart),
      args: {
        data: {
          type: 'DOMContentLoaded',
        },
      },
    }),
  );

  if (entry.domContentLoadedEventEnd)
    currentTrace.push(
      /** @type {Types.Events.MarkDOMContent} */ ({
        ...baseEvt,
        name: 'MarkDOMContent',
        ph: Phase.INSTANT,
        ts: toMicrosec(entry.domContentLoadedEventEnd),
        args: {
          data: {
            frame: frameData.frame,
            isMainFrame: true, // TODO(AD) - probably OK until iframes can opt into their parent's perf timeline but will need reviewing then
            isOutermostMainFrame: true,
            page: frameData.frame,
          },
        },
        s: 't',
      }),
    );

  if (entry.loadEventEnd)
    currentTrace.push(
      /** @type {Types.Events.MarkLoad} */ ({
        ...baseEvt,
        name: 'MarkLoad',
        ph: Phase.INSTANT,
        ts: toMicrosec(entry.loadEventEnd),
        args: {
          data: {
            frame: frameData.frame,
            isMainFrame: true, // TODO(AD) - probably OK until iframes can opt into their parent's perf timeline but will need reviewing then // TODO(AD) ???s
            isOutermostMainFrame: true,
            page: frameData.frame,
          },
        },
        s: 't',
      }),
    );
}

/** @param {PerfEntries.PerformanceLongTaskTiming} entry */
export function craftLongTaskEvent(entry) {
  currentTrace.push(innerHandleLongTask(entry));
}

/** @param {PerfEntries.PerformanceLongAnimationFrameTiming} entry */
export function handleLoafEvent(entry) {
  currentTrace.push(...innerHandleLoAF(entry));
}

/** @param {PerformanceEventTiming} entry */
export function craftEventTimingEvent(entry) {
  const {cancelable, duration, processingEnd, processingStart, interactionId} = entry;
  const id = getId();

  /** @type {Types.Events.EventTimingBegin} */
  const beginEvent = {
    ...baseEvt,
    name: /** @type {Types.Events.Name.EVENT_TIMING} */ ('EventTiming'),
    ts: toMicrosec(entry.startTime),
    args: {
      data: {
        frame: frameData.frame,
        cancelable,
        duration: Ms(duration),
        processingEnd: Ms(processingEnd),
        processingStart: Ms(processingStart),
        interactionId,
        interactionOffset: ++totalInteractionCount, // https://crrev.com/c/5009064
        nodeId: /** @type {DOM.BackendNodeId} */ (-1), // This is invalid, but we have no way of determining what backendNodeId it should be.
        type: entry.name,
        timeStamp: Ms(entry.startTime),
        // nodeId, enqueuedToMainThreadTime, interactionOffset
      },
    },
    ph: Phase.ASYNC_NESTABLE_START,
    id,
  };

  /** @type {Types.Events.EventTimingEnd} */
  const endEvent = {
    ...baseEvt,
    name: /** @type {Types.Events.Name.EVENT_TIMING} */ ('EventTiming'),
    ts: toMicrosec(entry.startTime + entry.duration),
    ph: Phase.ASYNC_NESTABLE_END,
    id,
    args: {},
  };

  currentTrace.push(beginEvent, endEvent);
}

//  {"args":{"data":{"cumulative_score":0.00020859991195191097,"frame_max_distance":130,"had_recent_input":false,
//                   "impacted_nodes":[{"new_rect":[1012,0,138,52],"node_id":13,"old_rect":[1142,0,8,52]}],
//                   "is_main_frame":true,"last_input_timestamp":0,"overall_max_distance":130,"region_rects":[[1012,0,138,52]],"score":0.00020859991195191097,"weighted_score_delta":0.00020859991195191097},
//           "frame":"7E553CAB71D8D9245E375B2649BD046C"},
//   "cat":"loading","name":"LayoutShift","ph":"I","pid":97815,"s":"t","tid":259,"ts":195103676695,"tts":761382},
/** @param {PerfEntries.LayoutShift} entry */
export function craftLayoutShiftEvent(entry) {
  const cumulativeScoreSoFar = currentTrace.filter(Types.Events.isLayoutShift).reduce((acc, cur) => acc + (cur.args.data?.score ?? 0), 0);

  /** @type {Types.Events.LayoutShift} */
  const evt = {
    ...baseEvt,
    name: /** @type {Types.Events.LayoutShift['name']} */ ('LayoutShift'),
    cat: 'loading',
    ph: Phase.INSTANT, // Instant. Current OPP relies on Frame data to extend the 'duration' of the Layout Shift item within the frame. (Kinda dumb, but w/e.)
    ts: toMicrosec(entry.startTime),
    args: {
      data: {
        score: entry.value,
        weighted_score_delta: entry.value,
        cumulative_score: entry.value + cumulativeScoreSoFar,
        had_recent_input: entry.hadRecentInput,
        // @ts-expect-error last_input_timestamp is missing from LayoutShiftData interface
        last_input_timestamp: entry.lastInputTime * 1000, // TODO Remove this?
        impacted_nodes: entry.sources.map(source => {
          return {
            old_rect: [source.previousRect.left, source.previousRect.top, source.previousRect.width, source.previousRect.height],
            new_rect: [source.currentRect.left, source.currentRect.top, source.currentRect.width, source.currentRect.height],
            node_id: /** @type {DOM.BackendNodeId} */ (-1), // This is invalid, but we have no way of determining what backendNodeId it should be.
          };
        }),
      },
    },
  };

  currentTrace.push(evt);
}

/**
 * Handle LCP, FCP, FP
 * @param {PerformancePaintTiming} entry */
export function craftMetricEvent(entry) {
  if (entry.entryType === 'largest-contentful-paint') {
    currentTrace.push(
      /** @type {Types.Events.LargestContentfulPaintCandidate} */ ({
        ...baseEvt,
        cat: 'loading,rail,devtools.timeline',
        ph: Phase.MARK,
        ts: toMicrosec(entry.startTime),
        name: 'largestContentfulPaint::Candidate',
        args: {
          data: {
            candidateIndex: 1,
            isMainFrame: true,
            isOutermostMainFrame: true,
            navigationId: frameData.navigationId,
            nodeId: /** @type {DOM.BackendNodeId} */ (150),
            size: 15904,
            type: 'text',
            loadingAttr: '', // TODO: Maybe we can extract loading=lazy signal for this.
          },
          frame: frameData.frame,
        },
        // args.data.nodeId points to the element. that's in `entry.element` but.. can't serialize that.
        // TODO: figure out if i wanna do something harder here. like nodePath
      }),
    );
    return;
  }

  // {"args":{"data":{"navigationId":"CEB90840AB5C1B51FA5915BD9DC3A3B0"},"frame":"36DDC2C0C9121FDE538CCD59D3AF99B1"},"cat":"loading,rail,devtools.timeline","name":"firstContentfulPaint","ph":"R","pid":90531,"s":"t","tid":259,"ts":405411455878},
  // {"args":{"data":{"candidateIndex":1,"isMainFrame":true,"isOutermostMainFrame":true,"navigationId":"CEB90840AB5C1B51FA5915BD9DC3A3B0","nodeId":150,"size":15904,"type":"text"},"frame":"36DDC2C0C9121FDE538CCD59D3AF99B1"},"cat":"loading,rail,devtools.timeline","name":"largestContentfulPaint::Candidate","ph":"R","pid":90531,"s":"t","tid":259,"ts":405411455972}
  let name = '';
  if (entry.name === 'first-contentful-paint') {
    name = 'firstContentfulPaint';
  } else if (entry.name === 'first-paint') {
    name = 'firstPaint';
  } else {
    console.warn('Handling unexpected metric event', entry.entryType, entry.name);
  }

  currentTrace.push(
    /** @type {Types.Events.FirstContentfulPaint|Types.Events.FirstPaint} */ ({
      ...baseEvt,
      name,
      cat: 'loading,rail,devtools.timeline',
      ph: Phase.MARK,
      ts: toMicrosec(entry.startTime),
      args: {data: {navigationId: frameData.navigationId}, frame: frameData.frame},
    }),
  );
}

export function addBaselineTraceEvents() {
  /** @type {Types.Events.Event} */
  const metaEvtBase = {
    ...baseEvt,
    cat: '__metadata',
    ph: Phase.METADATA,
  };

  currentTrace.push(
    /** @type {Types.Events.Metadata} */ ({
      ...metaEvtBase,
      name: 'process_labels',
      args: {labels: 'ProcessLabel'},
      ts: μs(0),
    }),
  );

  // {"args":{"name":"CrRendererMain"},"cat":"__metadata","name":"thread_name","ph":"M","pid":22783,"tid":259,"ts":0},
  // Defines the renderer main thread
  currentTrace.push(
    /** @type {Types.Events.ThreadName} */ ({
      ...metaEvtBase,
      name: 'thread_name',
      args: {name: 'CrRendererMain'},
      ts: μs(0),
    }),
  );

  // {"args":{"name":"Renderer"},"cat":"__metadata","name":"process_name","ph":"M","pid":97815,"tid":0,"ts":0},

  currentTrace.push(
    /** @type {Types.Events.ProcessName} */ ({
      ...metaEvtBase,
      name: 'process_name',
      args: {name: 'Renderer'},
      ts: μs(0),
    }),
  );

  currentTrace.push(
    /** @type {Types.Events.TracingStartedInBrowser} */ ({
      ...metaEvtBase,
      cat: 'disabled-by-default-devtools.timeline',
      name: 'TracingStartedInBrowser',
      ph: Phase.INSTANT,
      s: 't',
      args: {
        data: {
          frameTreeNodeId: 1,
          persistentIds: true,
          // TODO.. this is missing something. we still dont create pageFrames like we should
          // …Maybe its fine in new engine now.
          // https://source.chromium.org/chromium/chromium/src/+/main:third_party/devtools-frontend/src/front_end/models/timeline_model/TimelineModel.ts;l=1226-1266;drc=269e9ae3ebd8d9c79fa42e19a8674d45afd8cc9f
          frames: [frameData],
        },
      },
    }),
  );

  // FrameCommittedInBrowser
  // {"args":{"data":{"frame":"B507DC2BCAB0EA9F39380A5512008E5E","name":"","processId":22783,"url":"https://www.paulirish.com/"}},"cat":"disabled-by-default-devtools.timeline","name":"FrameCommittedInBrowser","ph":"I","pid":2988,"s":"t","tid":259,"ts":18755315652,"tts":409464439},
  currentTrace.push(
    /** @type {Types.Events.FrameCommittedInBrowser} */ ({
      ...metaEvtBase,
      cat: 'disabled-by-default-devtools.timeline',
      name: 'FrameCommittedInBrowser',
      ph: Phase.INSTANT,
      args: {
        data: frameData,
      },
    }),
  );
}

/**
 * @param {JSSelfProfiling.ProfilerTrace} selfProfile
 */
export function constructCpuProfileEvents(selfProfile) {
  const cpuProfile = selfProfileToCPUProfile(selfProfile);
  const profilerChunkEvts = cpuProfileToProfileChunk(cpuProfile);
  currentTrace.push(...profilerChunkEvts);
}

/**
 * The protocol Profile interface is neutral and defines the id attributes on nodes and samples as numbers.
 * same as the timeDeltas, instead of the utility types used on the Trace side.
 * This generates some type inference problems that we might want to express better in our own type definition files.
 * @param {CPUProfileDataModel.ExtendedProfile} cpuProfile
 */
function cpuProfileToProfileChunk(cpuProfile) {
  const {nodes, samples, timeDeltas, endTime} = cpuProfile;

  const id = getId();

  /** @type {Types.Events.Profile} */
  const profileEvt = {
    ...baseEvt,
    name: /** @type {Types.Events.Profile['name']} */ ('Profile'),
    cat: 'disabled-by-default-v8.cpu_profiler',
    ts: μs(1),
    args: {
      data: {
        startTime: μs(0),
        // @ts-expect-error endTime is missing from ArgsData
        endTime,
      },
    },
    ph: Phase.SAMPLE,
    id,
  };

  /** @type {Types.Events.ProfileChunk} */
  const profileChunkEvt = {
    ...baseEvt,
    name: /** @type {Types.Events.ProfileChunk['name']} */ ('ProfileChunk'),
    cat: 'disabled-by-default-v8.cpu_profiler',
    // Hack: Use one to avoid some mishandling in the devtools of valid trace events
    // with a ts of 0. We should fix the bug there, but making this a microsecond off
    // seems an okay tradeoff.
    ts: μs(1),
    args: {
      data: {
        cpuProfile: {
          // @ts-expect-error id attributes are incompatible (see comment on the function header)
          nodes,
          // @ts-expect-error id attributes are incompatible (see comment on the function header)
          samples,
        },
        // @ts-expect-error timeDeltas is of type number[] but expected MicroSeconds[]
        timeDeltas,
      },
    },
    ph: Phase.SAMPLE,
    id,
  };

  return [profileEvt, profileChunkEvt];
}

function flagInvalidData() {
  /** @param {any} obj */
  function checkForNaN(obj) {
    if (typeof obj !== 'object') return;
    Object.entries(obj).forEach(([key, value]) => {
      if (typeof value === 'number' && isNaN(value)) {
        console.warn(`Ruhroh. NaN found on (${key}) within:`, obj);
        if (globalThis.process?.env.NODE_TEST_CONTEXT) throw new Error(`NaN found on (${key}) within: ${JSON.stringify(obj)}`);
      }
    });
  }
  currentTrace.forEach(evt => {
    checkForNaN(evt);
    if (evt.args) {
      checkForNaN(evt.args);
      checkForNaN(evt.args.data);
    }

    if (typeof evt.dur === 'number' && evt.dur < 0) {
      console.warn(`Ruhroh. Negative duration found on:`, evt);
      if (globalThis.process?.env.NODE_TEST_CONTEXT) throw new Error(`Negative duration found on: ${JSON.stringify(evt)}`);
    }
  });
}
/**
 * @param {FieldTrace} fieldTrace
 * @return {Types.File.TraceFile}
 */
export function collectTrace(fieldTrace) {
  /** @type {Types.File.MetaData} */
  const metadata = {
    // TODO: use a navigation timestamp for startTime.
  };

  if (fieldTrace.sources?.length) {
    enhanceWithSources(fieldTrace);
    metadata.enhancedTraceVersion = 1;
  }

  // Add one more trace to give 100ms of zoom buffer.
  // TODO: Ideally i'd also add buffer in front via tracingStarted, but we're hugging zero already. (and going negative breaks the OverviewPane)
  const profileEvt = currentTrace.find(e => e.name === 'Profile');
  // @ts-expect-error endTime
  const lastTs = profileEvt?.args?.data?.endTime ?? currentTrace.reduce((acc, e) => (e.ts + (e.dur ?? 0) > acc ? e.ts + (e.dur ?? 0) : acc), 0);

  const lastEvent = {
    ...baseEvt,
    name: 'RunTask',
    cat: 'disabled-by-default-devtools.timeline',
    ts: μs(Math.floor(lastTs + 100_000)),
    dur: μs(2),
  };
  currentTrace.push(lastEvent);

  flagInvalidData();

  // Prefered order (top to bottom in flamechart)
  const preferredSortOrderByName = ['RunTask', 'FunctionCall', 'ProfileCall'];
  // Sort by ts (asc), then dur (desc), then preferredSortOrderByName position (asc)
  currentTrace.sort((a, b) => {
    const ret = a.ts - b.ts || (b.dur ?? 0) - (a.dur ?? 0);
    if (ret !== 0) return ret;
    const aI = preferredSortOrderByName.indexOf(a.name);
    const bI = preferredSortOrderByName.indexOf(b.name);
    // if (aI === -1 || bI === -1) {
    //   console.warn('Need a sort tiebreaker but it\'s undefined', a.name, b.name, aI, bI);
    // }
    return aI - bI;
  });

  return {metadata, traceEvents: currentTrace};
}
