import {Phase} from './phase.js';
import {baseEvt, μs, currentTrace} from './trace.js';

/** @import {FieldTrace}  from '../../../types/fieldtrace.js' */
/** @import * as ChromiumTrace from '../../../types/chromium-trace.js' */

/**
 *
 * @param {FieldTrace} fieldTrace
 */

export function enhanceWithSources(fieldTrace) {
  const {sources} = fieldTrace;
  if (!sources?.length) return;
  // TODO: scriptid should agree with same in cpuprofile/loaf.
  for (const source of sources || []) {
    /** @type {ChromiumTrace.RundownScriptCompiled} */
    const scriptCompiled = {
      ...baseEvt,
      name: source.isModule ? 'ModuleEvaluated' : 'ScriptCompiled',
      cat: 'disabled-by-default-devtools.target-rundown',
      ts: μs(0),
      dur: μs(1),
      ph: Phase.COMPLETE,
      args: {
        data: {
          frame: source.frameId,
          frameType: source.frameType,
          url: source.url,
          isolate: '0x1',
          v8context: '0x1',
          origin: '<origin>', // this ok?
          scriptId: source.scriptId,
        },
      },
    };
    /** @type {ChromiumTrace.RundownScript} */
    const rundownScript = {
      ...baseEvt,
      name: 'ScriptCatchup',
      cat: 'disabled-by-default-devtools.v8-source-rundown',
      ts: μs(0),
      dur: μs(1),
      ph: Phase.COMPLETE,
      args: {
        data: {
          isolate: '0x1',
          executionContextId: '0x1',
          isModule: source.isModule,
          hasSourceUrl: source.hasSourceUrl,
          url: source.url,
          hash: undefined,
          sourceUrl: source.sourceUrl,
          sourceMapUrl: source.sourceMapUrl,
          scriptId: source.scriptId,
        },
      },
    };
    /** @type {ChromiumTrace.RundownScriptSource} */
    const rundownScriptSource = {
      ...baseEvt,
      name: 'ScriptCatchup',
      cat: 'disabled-by-default-devtools.v8-source-rundown-sources',
      ts: μs(0),
      dur: μs(1),
      ph: Phase.COMPLETE,
      args: {
        data: {
          isolate: 0x1,
          scriptId: source.scriptId,
          length: source.content?.length,
          sourceText: source.content,
        },
      },
    };
    currentTrace.push(scriptCompiled, rundownScript, rundownScriptSource);
  }

  /** @type {Record<string, number>} */
  const scriptSrcById = {};
  sources.forEach(source => {
    scriptSrcById[source.url] = source.scriptId;
  });

  // Patchup loaf data to match scriptIds
  currentTrace.forEach(evt => {
    //@ts-expect-error
    if (evt.args?.data?.scriptId && evt.args?.data?.url) {
      //@ts-expect-error
      evt.args.data.scriptId = scriptSrcById[evt.args.data.url];
    }

    //@ts-expect-error
    if (evt.args?.scriptId && evt.args?.url) {
      //@ts-expect-error
      evt.args.scriptId = scriptSrcById[evt.args.url];
    }
    //@ts-expect-error
    if (evt.callFrame?.scriptId && evt.callFrame?.url) {
      //@ts-expect-error
      evt.callFrame.scriptId = scriptSrcById[evt.callFrame.url];
    }
  });

  //  TODO:also handle profilechunks
  // const profileChunk = currentTrace.find(e => e.name === 'ProfileChunk');
}
