import {toMicrosec, baseEvt, craftUserTimingForDebugging, frameData} from './trace.js';
import {Phase} from './phase.js';

/** @import * as PerfEntries from '../../../types/perfentries') */
/** @import {Types} from '@paulirish/trace_engine' */
// TODO: Migrate these types to trace_engine and re-adopt from there
/** @import {LoafEvents, AnimationFrameEvent,BeginMainFrame} from '../../../types/chromium-trace' */

/** @param {PerfEntries.PerformanceLongTaskTiming} entry */
export function innerHandleLongTask(entry) {
  /** @type {Types.Events.RunTask} */
  const tevt = {
    ...baseEvt,
    // Long Tasks are NOT the same thing as RunTasks, (per my Feb 2023 findings) but.. no trace event equivalent exists.
    // TODO: Find a resolution to this.
    name: /** @type {Types.Events.Name.RUN_TASK} */ ('RunTask'),
    cat: 'disabled-by-default-devtools.timeline',
    ts: toMicrosec(entry.startTime),
    dur: toMicrosec(entry.duration),
    args: {
      // @ts-expect-error attribution is not part of the ArgsData interface
      attribution: entry.attribution,
    },
  };

  return tevt;
}

/**
 * @param {PerfEntries.PerformanceLongAnimationFrameTiming} entry
 * @return {Array<Types.Events.Event|AnimationFrameEvent>}
 */
export function innerHandleLoAF(entry) {
  const evts = [];
  // Edge-case: toJSON needed if this is run clientside.
  const entryWithoutScripts = {...(entry.toJSON?.() || entry), scripts: []};
  craftUserTimingForDebugging(entryWithoutScripts, 'Long Animation Frames', 'loAF');
  /**
   * https://developer.chrome.com/docs/web-platform/long-animation-frames#advantages_of_looking_at_frames_instead_of_tasks
   * Start Time                         startTime
   * End Time                           startTime + duration.
   * Work duration                      renderStart ? renderStart - startTime : duration
   * Render duration                    renderStart ? (startTime + duration) - renderStart: 0
   * Render: Pre-layout duration        styleAndLayoutStart ? styleAndLayoutStart - renderStart : 0
   * Render: Style and Layout duration  styleAndLayoutStart ? (startTime + duration) - styleAndLayoutStart : 0
   *
   *
   * renderStart == beginMainFrame
   * endTime = Commit. end of BMF
   */

  // entry.duration is stored as int, which means it's floor'ed (at the very least)
  // I'll add 0.1ms just to make something visible
  const loafDuration = Math.max(entry.duration, entry.styleAndLayoutStart - entry.startTime + 0.1);
  const endMs = entry.startTime + loafDuration;
  const beginMainFrameStart = entry.renderStart;
  if (entry.styleAndLayoutStart < beginMainFrameStart) {
    console.warn('styleAndLayoutStart found before BMF!?');
  }
  const beginMainFrameDuration = endMs - beginMainFrameStart;

  if (beginMainFrameStart !== 0) {
    // This can be 0 in the loAF. Don't treat zero as valid.
    evts.push(
      /** @type {BeginMainFrame} */ ({
        ...baseEvt,
        name: 'ProxyMain::BeginMainFrame',
        ts: toMicrosec(beginMainFrameStart),
        dur: toMicrosec(beginMainFrameDuration),
        args: {},
      }),
    );
  }

  evts.push(
    /** @type {LoafEvents.AnimationFrameGroupingEvent} */ ({
      ...baseEvt,
      // Animation frame and its other events are missing from the known event names, for now.
      name: /** @type {LoafEvents.Name.AnimationFrame} */ ('AnimationFrame'),
      ph: Phase.ASYNC_NESTABLE_START,
      ts: toMicrosec(entry.startTime),
      args: {
        animation_frame_timing_info: {
          blocking_duration_ms: entry.blockingDuration,
          duration_ms: entry.duration,
          num_scripts: entry.scripts.length,
        },
      },
    }),
  );

  if (entry.firstUIEventTimestamp !== 0) {
    evts.push(
      /** @type {LoafEvents.AnimationFrameInstantEvent} */ ({
        ...baseEvt,
        name: /** @type {LoafEvents.Name.AnimationFrameFirstUIEvent} */ ('AnimationFrame::FirstUIEvent'),
        ph: Phase.ASYNC_NESTABLE_INSTANT,
        ts: toMicrosec(entry.firstUIEventTimestamp),
      }),
    );
  }

  // scripts: FunctionCall for each.
  entry.scripts.forEach(script => {
    craftUserTimingForDebugging(script, 'Long Animation Frames', 'script');

    // script.duration is stored as int, which means it's floor'ed (at the very least) https://source.chromium.org/chromium/chromium/src/+/main:third_party/blink/renderer/core/timing/performance_script_timing.h;l=25-26;drc=63635fff4bce239256a42d5f1a28fa3d0934bf35
    // I'll add 0.1ms just to make something visible
    const scriptDurationMs = Math.max(script.duration, script.executionStart - script.startTime + 0.1);
    const compileDurationMs = script.executionStart - script.startTime;
    // {"args":{},"cat":"disabled-by-default-v8.compile","dur":116,"name":"V8.CompileCode","ph":"X","pid":68496,"tdur":115,"tid":259,"ts":1090123466557,"tts":54296370,"selfTime":33},
    evts.push(
      /** @type {Types.Events.Event} */ ({
        // Interestingly there's not a specific type for this
        ...baseEvt,
        cat: 'disabled-by-default-v8.compile',
        name: 'V8.CompileCode',
        ts: toMicrosec(script.startTime),
        dur: toMicrosec(compileDurationMs),
      }),
    );

    //    {"args":{"data":{"columnNumber":32,"frame":"2BD2BE1FCE3FB157EF97FE70E81E11E6",
    //    "functionName":"data.args.<computed>","lineNumber":24,"scriptId":"27744","url":"/common/timers.es2016.js"}},
    //    "cat":"devtools.timeline","dur":369317,"name":"FunctionCall","ph":"X","pid":68496,"tdur":369232,"tid":259,"ts":1090123089778,"tts":53919676},
    evts.push(
      /** @type {Types.Events.FunctionCall} */ ({
        ...baseEvt,
        name: 'FunctionCall',
        ts: toMicrosec(script.executionStart),
        dur: toMicrosec(scriptDurationMs - compileDurationMs),
        args: {
          data: {
            lineNumber: 0,
            columnNumber: script.sourceCharPosition, // This is wrong, but.. might be right if it was minified to 1 line.
            frame: frameData.frame,
            functionName: script.sourceFunctionName,
            scriptId: -1, // Not valid.
            url: script.sourceURL,
            _invoker: script.invoker, // invoker: "https://tailwindcss.com/_next/static/chunks/framework-ce84985cd166733a.js",
            _invokerType: script.invokerType, // invokerType: "classic-script",
            _windowAttribution: script.windowAttribution, // windowAttribution: "self",
          },
        },
      }),
    );

    // We have a function name so lets call it out..  Unfortunately we'll have an extra function call if JS Self Profile is included.
    // Using ProfileCall works a tad better than EventDispatch.
    // @ts-expect-error TODO: missing nodeId, sampleIndex, profileId
    const profileCall = /** @type {Types.Events.SyntheticProfileCall} */ ({
      ...baseEvt,
      name: 'ProfileCall',
      ts: toMicrosec(script.executionStart),
      dur: toMicrosec(scriptDurationMs - compileDurationMs),
      callFrame: {
        codeType: 'JS',
        lineNumber: 0,
        columnNumber: script.sourceCharPosition, // This is wrong, but.. might be right if it was minified to 1 line.
        frame: frameData.frame,
        functionName: `${script.sourceFunctionName || '(anonymous)'} (loAF script)`,
        scriptId: -1, // Not valid.
        url: script.sourceURL,
      },
      // nodeId: -1,
      // sampleIndex: -1,
      // profileId: '',
    });
    evts.push(profileCall);

    if (script.startTime < script.executionStart) {
      // TODO: add a type for this one.
      evts.push({
        ...baseEvt,
        name: /** @type {LoafEvents.Name.AnimationFrameScriptCompile} */ ('AnimationFrame::Script::Compile'),
        ph: Phase.ASYNC_NESTABLE_START,
        ts: toMicrosec(script.startTime),
        args: {
          data: {
            invokerType: script.invokerType,
            pauseDuration: script.pauseDuration,

            sourceLocationUrl: script.sourceURL,
            sourceLocationFunctionName: script.sourceFunctionName || '(anonymous)',
            sourceLocationCharPosition: script.sourceCharPosition,

            // not available on the attribution model, yet
            layoutDuration: 0, // script.layoutDuration
            styleDuration: 0, // script.styleDuration
          },
        },
      });

      evts.push({
        ...baseEvt,
        name: /** @type {LoafEvents.Name.AnimationFrameScriptCompile} */ ('AnimationFrame::Script::Compile'),
        ph: Phase.ASYNC_NESTABLE_END,
        ts: toMicrosec(script.executionStart),
      });
    }

    // TODO: add a type and doublecheck the casing of the args.
    evts.push({
      ...baseEvt,
      name: /** @type {LoafEvents.Name.AnimationFrameScriptExecute} */ ('AnimationFrame::Script::Execute'),
      ph: Phase.ASYNC_NESTABLE_START,
      ts: toMicrosec(script.startTime),
      args: {
        data: {
          invokerType: script.invokerType,
          pauseDuration: script.pauseDuration,

          sourceLocationUrl: script.sourceURL,
          sourceLocationFunctionName: script.sourceFunctionName || '(anonymous)',
          sourceLocationCharPosition: script.sourceCharPosition,

          // not available on the attribution model, yet
          layoutDuration: 0, // script.layoutDuration
          styleDuration: 0, // script.styleDuration
        },
      },
    });

    evts.push({
      ...baseEvt,
      name: /** @type {LoafEvents.Name.AnimationFrameScriptExecute} */ ('AnimationFrame::Script::Execute'),
      ph: Phase.ASYNC_NESTABLE_END,
      ts: toMicrosec(script.startTime + script.duration),
    });

    // Forced style
    // TODO: This merges poorly with the sampling data. Because it might be multiple.. we don't know how its split up. But just throwing the event in there can lead to an innacurate flamechart. :/
    if (script.forcedStyleAndLayoutDuration) {
      const scriptEnd = script.startTime + script.duration;
      const forcedStyleAndLayoutStart = scriptEnd - script.forcedStyleAndLayoutDuration;
      addStyleAndLayoutPair(forcedStyleAndLayoutStart, script.forcedStyleAndLayoutDuration);
    }

    // TODO: make native JS profilecall to highlight pause duration
    // pauseDuration: 0, // Total time spent in "pausing" synchronous operations (alert, synchronous XHR)
  });

  evts.push({
    ...baseEvt,
    name: /** @type {LoafEvents.Name.AnimationFrame} */ ('AnimationFrame'),
    ph: Phase.ASYNC_NESTABLE_END,
    ts: toMicrosec(endMs),
  });

  /**
   * @param {number} start
   * @param {number} duration
   */
  function addStyleAndLayoutPair(start, duration) {
    // {"args":{"beginData":{"frame":"C45E6CB8A96AD582632AECC1CDCBDC57"},"elementCount":3},"cat":"blink,devtools.timeline","dur":137,"name":"UpdateLayoutTree","ph":"X","pid":67459,"tdur":135,"tid":259,"ts":23481127528,"tts":1571081,"selfTime":137},
    // {"args":{"beginData":{"dirtyObjects":3,"frame":"C45E6CB8A96AD582632AECC1CDCBDC57","partialLayout":false,"totalObjects":3},"endData":{"layoutRoots":[{"depth":1,"nodeId":2,"quads":[[0,0,1762,0,1762,1988,0,1988]]}]}},"cat":"devtools.timeline","dur":47,"name":"Layout","ph":"X","pid":67459,"tdur":42,"tid":259,"ts":23479704809,"tts":153676,"selfTime":47},
    const half = toMicrosec(duration / 2 - 0.001); // 1 microsec adjustment to avoid losing items in the flamechart
    evts.push(
      /** @type {Types.Events.RecalcStyle} */ ({
        ...baseEvt,
        name: 'UpdateLayoutTree',
        ts: toMicrosec(start),
        dur: half,
        args: {
          beginData: {frame: frameData.frame},
          elementCount: -1,
        },
      }),
    );
    evts.push(
      /** @type {Types.Events.Layout} */ ({
        ...baseEvt,
        name: 'Layout',
        ts: toMicrosec(start) + half,
        dur: half,
        args: {
          beginData: {dirtyObjects: -1, totalObjects: -1, partialLayout: false, frame: frameData.frame},
          endData: {layoutRoots: [{depth: 1, nodeId: -1, quads: [[0, 0, 1979, 0, 1979, 1982, 0, 1982]]}]},
        },
      }),
    );

    evts.push({
      ...baseEvt,
      name: /** @type {LoafEvents.Name.AnimationFrameStyleAndLayout} */ ('AnimationFrame::StyleAndLayout'),
      ph: Phase.ASYNC_NESTABLE_START,
      ts: toMicrosec(start),
    });

    evts.push({
      ...baseEvt,
      name: /** @type {LoafEvents.Name.AnimationFrameStyleAndLayout} */ ('AnimationFrame::StyleAndLayout'),
      ph: Phase.ASYNC_NESTABLE_END,
      ts: toMicrosec(endMs - start),
    });
  }

  // Rendering at the end..
  if (entry.styleAndLayoutStart !== 0) {
    // In reality, this loaf time includes these 6 operations:
    //    style, layout, pre-paint, paint, layerize, commit.

    const operationDuration = ((endMs - entry.styleAndLayoutStart) * 1) / 6;
    addStyleAndLayoutPair(entry.styleAndLayoutStart, operationDuration * 2);

    ['PrePaint', 'Paint', 'Layerize', 'Commit'].forEach((name, i) => {
      // These will be evenly spaced and start after layout.
      const start = entry.styleAndLayoutStart + (i + 2) * operationDuration;
      //   {"args":{"data":{"frame":"C45E6CB8A96AD582632AECC1CDCBDC57","isMainFrame":true,"isOutermostMainFrame":true,"page":"C45E6CB8A96AD582632AECC1CDCBDC57"}},"cat":"devtools.timeline","dur":1994,"name":"PrePaint","ph":"X","pid":61792,"tdur":1993,"tid":259,"ts":19395174465,"tts":2059208,"selfTime":1994},
      //   {"args":{"data":{"clip":[-8388608,-8388608,8388607,-8388608,8388607,8388607,-8388608,8388607],"frame":"C45E6CB8A96AD582632AECC1CDCBDC57","layerId":0,"nodeId":2}},"cat":"devtools.timeline,rail","dur":4770,"name":"Paint","ph":"X","pid":61792,"tdur":4769,"tid":259,"ts":19395182803,"tts":2067544,"selfTime":2573},
      //   {"args":{"data":{"frame":"C45E6CB8A96AD582632AECC1CDCBDC57","isMainFrame":true,"isOutermostMainFrame":true,"page":"C45E6CB8A96AD582632AECC1CDCBDC57"}},"cat":"devtools.timeline","dur":1284,"name":"Layerize","ph":"X","pid":61792,"tdur":1283,"tid":259,"ts":19395187579,"tts":2072319,"selfTime":1284},
      //   {"args":{"frameSeqId":58679,"layerTreeId":6},"cat":"disabled-by-default-devtools.timeline","dur":69,"name":"Commit","ph":"X","pid":60982,"tdur":69,"tid":259,"ts":19393187015,"tts":14460682},
      evts.push(
        /** @type {Types.Events.Complete} */ ({
          // Lacking more specific type. That's probably ok.
          ...baseEvt,
          name,
          ts: toMicrosec(start),
          dur: toMicrosec(operationDuration - 0.001), // 1 microsec adjustment to avoid losing items in the flamechart
          args: {
            data: {
              // This is a mix of all of them, but.. probably doesn't matter.
              frame: frameData.frame,
              isMainFrame: true,
              isOutermostMainFrame: true,
              page: frameData.frame,
              frameSeqId: -1,
              layerTreeId: -1,
              clip: [-1, -1, -1, -1, -1, -1, -1, -1],
              nodeId: -1,
              layerId: -1,
            },
          },
        }),
      );
    });

    evts.push({
      ...baseEvt,
      name: /** @type {LoafEvents.Name.AnimationFrameRender} */ ('AnimationFrame::Render'),
      ph: Phase.ASYNC_NESTABLE_START,
      ts: toMicrosec(beginMainFrameStart),
    });

    evts.push({
      ...baseEvt,
      name: /** @type {LoafEvents.Name.AnimationFrameRender} */ ('AnimationFrame::Render'),
      ph: Phase.ASYNC_NESTABLE_END,
      ts: toMicrosec(beginMainFrameDuration),
    });

    // TODO: Add the AnimationFrame::Presentation event by analysing the frames events.
    // By how some of the traces behave, the AnimationFrame::Presentation event happen, after the AnimationFrame 'e' event
    // and just before the SwapEndToPresentationCompositorFrame 'e' event.
  }

  return evts;
}
