import * as Trace from './trace/trace.js';

/** @import * as PerfEntries from '../../types/perfentries') */

/** @import {FieldTrace}  from '../../types/fieldtrace.js') */

/**
 * @param {FieldTrace} fieldTrace
 */
export function toTrace(fieldTrace) {
  Trace.reset();
  /** @type {PerformanceEntry[]} */
  const entries = Array.isArray(fieldTrace) ? fieldTrace : fieldTrace.entries; // TODO: remove legacy file support
  entries.sort((a, b) => a.startTime - b.startTime);

  for (const entry of entries) {
    switch (entry.entryType) {
      case 'navigation':
        Trace.handleNavigation(/** @type {PerformanceNavigationTiming} */ (entry));
        break;
      case 'resource':
        Trace.constructNetworkRequest(/** @type {PerformanceResourceTiming} */ (entry));
        break;
      case 'longtask':
        Trace.craftLongTaskEvent(/** @type {PerfEntries.PerformanceLongTaskTiming} */ (entry));
        break;
      case 'long-animation-frame':
        Trace.handleLoafEvent(/** @type {PerfEntries.PerformanceLongAnimationFrameTiming} */ (entry));
        break;
      case 'layout-shift':
        Trace.craftLayoutShiftEvent(/** @type {PerfEntries.LayoutShift} */ (entry));
        break;
      case 'event':
        Trace.craftEventTimingEvent(/** @type {PerformanceEventTiming} */ (entry));
        break;
      case 'paint':
      case 'largest-contentful-paint':
        Trace.craftMetricEvent(/** @type {PerformancePaintTiming} */ (entry));
        break;
      // TODO: remove. Legacy approach of using an artificial Perf Entry to hold the JS Self Profile
      case 'profiler-trace':
        Trace.constructCpuProfileEvents(/** @type {PerfEntries.PerformanceArtificialProfilerTraceEntry} */ (entry).profilerTrace);
        break;
      case 'mark':
      case 'measure':
        Trace.craftUTEvent(/** @type {PerformanceMark|PerformanceMeasure} */ (entry));
        break;
      case 'first-input':
      case 'visibility-state':
        // Nothing to do for these.
        break;
      default:
        console.warn('Unhandled eventType!', entry.entryType, entry.name);
        // Trace.craftUserTimingForDebugging(entry);
        break;
    }
  }

  if (fieldTrace.profile) {
    Trace.constructCpuProfileEvents(fieldTrace.profile);
  }

  const traceEvts = Trace.collectTrace(fieldTrace);
  return traceEvts;
}
